import { expect, test } from './browser-test.ts';
import { finishBoard, loadFixedBoard } from './game-fixture.ts';

test('matching and completing a game make no Web Audio API calls', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.addInitScript(() => {
    document.documentElement.dataset.audioApiCalls = '0';
    Object.defineProperty(window, 'AudioContext', {
      configurable: true,
      value: new Proxy(window.AudioContext, {
        construct() {
          const root = document.documentElement;
          root.dataset.audioApiCalls = String(Number(root.dataset.audioApiCalls) + 1);
          throw new Error('Unexpected Web Audio API call.');
        },
      }),
    });
  });
  await loadFixedBoard(page);
  await finishBoard(page);
  expect(await page.locator('html').getAttribute('data-audio-api-calls')).toBe('0');
  expect(errors).toEqual([]);
});

